// Expand a structured recurrence into concrete date windows.
// Pure calendar math in UTC (dates only); the +08:00 time is attached at the end,
// so the runtime timezone never shifts a day. Returns a refusal object or {occurrences}.
//
// Guards enforced here (the safety-critical part):
//   - frequency and start_date required
//   - an explicit end required: exactly a count OR an until_date (never open-ended)
//   - the series may not span more than one year from the start
//
// Inputs (from the agent via the Book Series tool):
//   frequency  'daily' | 'weekly'
//   by_days    ['MO','TU',...] for weekly (defaults to the start date's weekday)
//   start_date 'YYYY-MM-DD'
//   count      integer  (one of count / until_date required)
//   until_date 'YYYY-MM-DD'
//   all_day    boolean
//   time_start 'HH:MM'   (required unless all_day)
//   time_end   'HH:MM'
function expandDates(REQ) {
  const DOW = { SU:0, MO:1, TU:2, WE:3, TH:4, FR:5, SA:6 };
  const isDate = s => /^\d{4}-\d{2}-\d{2}$/.test(String(s || '').trim());
  const fmt = d => d.toISOString().slice(0, 10);

  const freq = String(REQ.frequency || '').trim().toLowerCase();
  const start = String(REQ.start_date || '').trim();
  const allDay = REQ.all_day === true || String(REQ.all_day).toLowerCase() === 'true';
  const t0 = String(REQ.time_start || '').trim();
  const t1 = String(REQ.time_end || '').trim();

  if (freq !== 'daily' && freq !== 'weekly')
    return { status: 'MISSING_DETAILS', reason: 'I need to know how often it repeats - daily or weekly.' };
  if (!isDate(start))
    return { status: 'MISSING_DETAILS', reason: 'I need the date the series starts on.' };
  if (!allDay && (!/^\d{1,2}:\d{2}$/.test(t0) || !/^\d{1,2}:\d{2}$/.test(t1)))
    return { status: 'MISSING_DETAILS', reason: 'I need a start and end time (or say it is all-day).' };

  const hasCount = REQ.count != null && String(REQ.count).trim() !== '' && Number(REQ.count) > 0;
  const hasUntil = isDate(REQ.until_date);
  if (!hasCount && !hasUntil)
    return { status: 'MISSING_END', reason: 'A repeating booking needs an end - a number of sessions or a stop date. How many, or until when?' };

  const startD = new Date(start + 'T00:00:00Z');
  if (isNaN(startD.getTime()))
    return { status: 'MISSING_DETAILS', reason: 'The start date is not a real date.' };

  const oneYear = new Date(startD); oneYear.setUTCFullYear(oneYear.getUTCFullYear() + 1);
  const untilD = hasUntil ? new Date(REQ.until_date + 'T00:00:00Z') : null;
  if (untilD && untilD < startD)
    return { status: 'MISSING_DETAILS', reason: 'The stop date is before the start date.' };
  if (untilD && untilD > oneYear)
    return { status: 'SPAN_TOO_LONG', reason: 'A repeating booking can run at most one year. Give a stop date within a year of the start, or a smaller count.' };

  // weekly day-of-week set (default to the start date's weekday).
  // Accepts an array or a comma string ("TU" or "MO,WE"); the agent passes a string.
  let byDays = Array.isArray(REQ.by_days)
    ? REQ.by_days.map(d => String(d).toUpperCase().slice(0, 2))
    : String(REQ.by_days || '').split(',').map(d => d.trim().toUpperCase().slice(0, 2)).filter(Boolean);
  if (freq === 'weekly' && !byDays.length) {
    byDays = [Object.keys(DOW).find(k => DOW[k] === startD.getUTCDay())];
  }
  const wanted = new Set(byDays.map(d => DOW[d]).filter(n => n != null));
  if (freq === 'weekly' && !wanted.size)
    return { status: 'MISSING_DETAILS', reason: 'Which day(s) of the week should it repeat on?' };

  const N = hasCount ? Number(REQ.count) : Infinity;
  const dates = [];
  const cur = new Date(startD);
  // Absolute iteration ceiling: one year of days plus slack. Prevents any runaway.
  for (let guard = 0; guard <= 372 && dates.length < N; guard++) {
    if (cur > oneYear) break;
    if (untilD && cur > untilD) break;
    if (freq === 'daily' || wanted.has(cur.getUTCDay())) dates.push(fmt(cur));
    cur.setUTCDate(cur.getUTCDate() + 1);
  }

  if (hasCount && dates.length < N)
    return { status: 'SPAN_TOO_LONG', reason: 'That many sessions would run past one year. Use a smaller count or a shorter interval.', got: dates.length, wanted: N };
  if (!dates.length)
    return { status: 'MISSING_DETAILS', reason: 'That pattern produced no dates - check the day(s) and range.' };

  const occurrences = dates.map(d => allDay
    ? { date: d, all_day: true }
    : { start_iso: d + 'T' + t0.padStart(5, '0') + ':00+08:00',
        end_iso:   d + 'T' + t1.padStart(5, '0') + ':00+08:00', all_day: false });

  return { status: 'OK', count: occurrences.length, occurrences };
}

// ---- Book Series expander: one Book Session input per occurrence, or a refusal ----
// PENDING 51 (2026-09-28): keep only the date / time text the model meant - "2027-10-05hq" or "14:00p" used
// to fail the date checks and come back as missing details.
const REQ = (function (o) {
  const out = Object.assign({}, o || {});
  const d = s => { const m = String(s == null ? '' : s).match(/\d{4}-\d{2}-\d{2}/); return m ? m[0] : s; };
  const t = s => { const m = String(s == null ? '' : s).match(/\d{1,2}:\d{2}/); return m ? m[0] : s; };
  ['start_date', 'until_date'].forEach(k => { if (typeof out[k] === 'string' && out[k]) out[k] = d(out[k]); });
  ['time_start', 'time_end'].forEach(k => { if (typeof out[k] === 'string' && out[k]) out[k] = t(out[k]); });
  return out;
})($('When Executed by Another Workflow').first().json);
// v4 (deterministic series): Series Direct passes the exact dates the requester approved - book those, not a re-expansion
const __given = String(REQ.dates || '').split(',').map(s => s.trim()).filter(s => /^\d{4}-\d{2}-\d{2}$/.test(s));
const __allDay = REQ.all_day === true || String(REQ.all_day).toLowerCase() === 'true';
const __t = s => String(s || '').padStart(5, '0');
const res = __given.length
  ? { status: 'OK', count: __given.length, occurrences: __given.map(d => __allDay ? { date: d, all_day: true }
      : { start_iso: d + 'T' + __t(REQ.time_start) + ':00+08:00', end_iso: d + 'T' + __t(REQ.time_end) + ':00+08:00', all_day: false }) }
  : expandDates(REQ);
const __prep = String(REQ.mode || '').trim().toLowerCase() === 'prepare';
if (res.status !== 'OK') {
  return [{ json: { _go:false, status:res.status, count:res.count||0,
    human: res.reason || ('Cannot build the series: ' + res.status) } }];
}
if (res.count > 16) {
  return [{ json: { _go:false, status:'TOO_MANY', count:res.count,
    human: 'That series is ' + res.count + ' sessions. I can book up to 16 at a time for now - book the first 16, a shorter run, or set the full series up in Google Calendar directly.' } }];
}
function nextDay(d){ const x=new Date(d+'T00:00:00Z'); x.setUTCDate(x.getUTCDate()+1); return x.toISOString().slice(0,10); }
return res.occurrences.map(function(o){
  const j = {
    _go:true,
    summary: REQ.summary, rooms: REQ.rooms,
    description: REQ.description || '', session_type: REQ.session_type || '',
    client: REQ.client || '', engineer: REQ.engineer || '',
    // v3: passed through so Book Session can check a new client against what the requester typed (Book v50).
    requester_text: REQ.requester_text || '',
    bookingType: REQ.bookingType || '', department: REQ.department || '', reference_data: REQ.reference_data || '',
    room_override: REQ.room_override === true || String(REQ.room_override).toLowerCase() === 'true', confirmed: __prep ? false : REQ.confirmed, series: !__prep,
    all_day: !!o.all_day,
    // v4: prepare mode runs each date through Book Session's prepare checks, as a single booking on that date
    mode: __prep ? 'prepare' : '', asked_text: REQ.asked_text || '', staff_data: REQ.staff_data || '', authority: REQ.authority || ''
  };
  if (o.all_day) { j.start_iso = o.date + 'T00:00:00+08:00'; j.end_iso = nextDay(o.date) + 'T00:00:00+08:00'; j._date = o.date; }
  else { j.start_iso = o.start_iso; j.end_iso = o.end_iso; j._date = o.start_iso.slice(0,10); }
  if (__prep) j.expected_date = j._date;
  return { json: j };
});

// Book Series aggregate: zip the Expand Dates occurrences with the per-date Book Session
// results (same order), report booked / skipped / failed, and set a status Guard Probe
// recognizes as backing a "Booked" claim.
const PB_SALT = '4539361661025d1d';
const pbNorm = s => String(s == null ? '' : s).replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/[*_]/g, '').replace(/\s+/g, ' ').trim();
const pbHash = s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
const seriesKey = (ref, f) => 'prep-s' + pbHash(PB_SALT + '|series|' + String(ref || '').trim() + '|' + pbNorm(f.Title) + '|' + (f.Dates || []).map(pbNorm).join(';') + '|' + pbNorm(f.Time) + '|' + pbNorm(f.Room));
const seriesCode = inputs => pbHash(PB_SALT + '|series-code|' + JSON.stringify(inputs));
const occ = $('Expand Dates').all().map(i => i.json).filter(o => o._go);
const results = $input.all().map(i => i.json);
// --- v4 (deterministic series): prepare mode - the card, written here, and the series stored for the yes ---------------
const REQ0 = $('When Executed by Another Workflow').first().json || {};
if (String(REQ0.mode || '').trim().toLowerCase() === 'prepare') {
  const MONP = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const DAYP = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const long = d => { const x = new Date(d + 'T00:00:00Z'); return DAYP[x.getUTCDay()] + ', ' + x.getUTCDate() + ' ' + MONP[x.getUTCMonth()] + ' ' + x.getUTCFullYear(); };
  const ok = [], taken = [];
  let first = null, ask = null;
  for (let i = 0; i < occ.length; i++) {
    const r = results[i] || {}, d = occ[i]._date;
    let P = null; try { P = r.prep_payload ? JSON.parse(r.prep_payload) : null; } catch (e) {}
    // v5: every date in the first date's room - one prepared in another room (no room named) means that room was not free
    if (r.status === 'PREPARED' && P && P.F && !r.needs_consent && (!first || pbNorm(P.F['Room']) === pbNorm(first.P.F['Room']))) { ok.push(d); if (!first) first = { r, P, d }; }
    else if (r.status === 'PREPARED' || r.reason === 'ROOM_OCCUPIED' || r.reason === 'ROOM_DECLINED') taken.push(d);
    else if (!ask) ask = r;
  }
  if (ask) return [{ json: { status: 'REJECTED', reason: ask.reason || 'FAILED', human: ask.human || 'Nothing was prepared.' } }];   // a question, as Book Session wrote it
  if (!first) return [{ json: { status: 'REJECTED', reason: 'ROOM_OCCUPIED',
    human: 'Nothing was prepared - the room is taken on every one of those dates (' + taken.map(long).join('; ') + '). Ask exactly this, in one message: "The room is taken on all of those dates. Another room or time?"' } }];
  const F = first.P.F;
  const shown = ok.map(long);
  // notes from the first date's card ("Not a usual ... room", "Want a holding room?") - never a date-specific one
  const _notes = String(first.r.summary_text || '').split('\n\n').slice(1, -1).join('\n').split('\n').map(s => s.trim())
    .filter(s => s && !/already passed|^Heads up: \S.* is booked|picked|No time given/i.test(s));
  const L = ['*' + F['Title'] + '*', '*Dates (' + ok.length + '):*'].concat(shown.map(s => '- ' + s), ['*Time:* ' + F['Time'], '*Room:* ' + F['Room']]);
  const _for = (String(F['Booked by'] || '').match(/\(for\s+([^)]+)\)/i) || [])[1]; if (_for) L.push('*For:* ' + _for.trim());
  const notes = _notes.slice();
  if (taken.length) notes.unshift('Heads up: ' + F['Room'] + ' is taken on ' + taken.map(long).join(', ') + ' - ' + (taken.length === 1 ? 'that date' : 'those dates') + ' left out.');
  const card = L.join('\n') + (notes.length ? '\n\n' + notes.join('\n') : '') + '\n\nConfirm to book.';
  const ref = String(first.P.ref || ((String(REQ0.description || '').match(/\bref:\s*([A-Z0-9]+)/) || [])[1]) || '').trim();
  const desc = (F['Engineer'] ? ['Engineer: ' + F['Engineer']] : []).concat(F['Arranger'] ? ['Arranger: ' + F['Arranger']] : [])   // v5: none for a room with no engineer
    .concat(String(REQ0.description || '').split('|').map(s => s.trim()).filter(s => s && !/^(engineer|arranger)\s*:/i.test(s))).join(' | ');
  const inputs = { summary: F['Title'], rooms: F['Room'], session_type: F['Session Type'] || '', client: /^none$/i.test(F['Client'] || '') ? '' : (F['Client'] || ''),
    engineer: F['Engineer'] || '', description: desc, bookingType: F['Booking Type'] || '', department: F['Department'] || '',
    room_override: F['Override'] === 'yes', all_day: !!occ[0].all_day,
    time_start: String(REQ0.time_start || ''), time_end: String(REQ0.time_end || ''), dates: ok.join(','),
    requester_text: String(REQ0.requester_text || '') };
  const key = ref ? seriesKey(ref, { Title: F['Title'], Dates: shown, Time: F['Time'], Room: F['Room'] }) : '';
  return [{ json: { status: 'PREPARED', card_text: card, title: F['Title'], dates: ok, skipped: taken, prep_key: key,
    prep_payload: JSON.stringify({ v: 1, kind: 'series', ref, code: seriesCode(inputs), inputs, card: { Title: F['Title'], Dates: shown, Time: F['Time'], Room: F['Room'] }, at: new Date().toISOString() }),
    human: 'The series card is ready and is sent to the requester automatically, exactly as prepared. Do not write anything about this booking yourself. Their yes books it - do not call Book Series.' } }];
}
const DOW = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const MON = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const wd  = d => DOW[new Date(d + 'T00:00:00Z').getUTCDay()];
const fmt = d => { const x = new Date(d + 'T00:00:00Z'); return MON[x.getUTCMonth()] + ' ' + x.getUTCDate() + ', ' + x.getUTCFullYear(); };
const booked = [], skipped = [], notConf = [], failed = [];
for (let i = 0; i < occ.length; i++) {
  const r = results[i] || {}, date = occ[i]._date;
  if (r.status === 'CREATED') booked.push(date);
  else if (r.reason === 'ROOM_OCCUPIED' || r.status === 'ROOM_DECLINED') skipped.push(date);
  else if (r.reason === 'NOT_CONFIRMED') notConf.push(date);
  else failed.push({ date: date, why: (r.reason || r.status || 'unknown') });
}
if (notConf.length && notConf.length === occ.length) {
  return [{ json: { status: 'NOT_CONFIRMED',
    human: 'This series is not approved yet. Present the full list of dates, end with the line "Confirm to book.", and stop - then book only after they reply yes.' } }];
}
const line = d => '- ' + fmt(d) + ' (' + wd(d) + ')';
const parts = [];
if (booked.length) parts.push('Booked ' + booked.length + ' session' + (booked.length === 1 ? '' : 's') + ':\n' + booked.map(line).join('\n'));
if (skipped.length) parts.push('Skipped - the room was already taken on:\n' + skipped.map(line).join('\n') + '\nWant these at a different time, or a nearby day?');
if (failed.length) parts.push('Could not book:\n' + failed.map(f => line(f.date) + ' - ' + f.why).join('\n'));
const human = parts.join('\n\n') || 'Nothing was booked.';
const status = booked.length ? 'BOOKED_SERIES' : ((skipped.length || failed.length) ? 'NONE_BOOKED' : 'EMPTY');
return [{ json: { status: status, booked: booked, skipped: skipped, failed: failed, human: human } }];

// Series Out (Book Series v4): hands the prepared series back unchanged - Store Series only saved it. If the save failed the
// card still goes out; at the yes main finds nothing stored, so Series Direct does not run and the model is told the series
// is approved (Gate Context's seriesNotice) - never a booking with missing details.
return $('Aggregate').all().map(i => ({ json: Object.assign({}, i.json, { prep_stored: (function () { try { const s = $('Store Series').first().json || {}; return !s.error; } catch (e) { return false; } })() }) }));
